```java
import java.io.*;
import java.net.ServerSocket;
import java.util.Arrays;
import java.util.List;

public class SecureServer {
    // Define a "whitelist" of classes that are allowed to be deserialized
    private static final List<String> ALLOWED_CLASSES = Arrays.asList(
        "java.lang.String",
        "java.util.ArrayList",
        "com.myapp.models.UserDTO" // Example of a specific safe class
    );

    public static void main(String[] args) throws Exception {
        ServerSocket serverSocket = new ServerSocket(8080);
        System.out.println("Secure server listening on 8080...");

        while (true) {
            try (Socket clientSocket = serverSocket.accept();
                 // Use a custom ObjectInputStream that implements look-ahead validation
                 SecureObjectInputStream in = new SecureObjectInputStream(clientSocket.getInputStream())) {

                Object obj = in.readObject();
                System.out.println("Received: " + obj.toString());

            } catch (Exception e) {
                System.err.println("Blocked unauthorized deserialization attempt: " + e.getMessage());
            }
        }
    }

    // Custom implementation of ObjectInputStream to validate classes before instantiation
    static class SecureObjectInputStream extends ObjectInputStream {
        public SecureObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            // Check if the class being deserialized is in our whitelist
            if (!ALLOWED_CLASSES.contains(desc.getName())) {
                throw new InvalidClassException("Unauthorized deserialization attempt", desc.getName());
            }
            return super.resolveClass(desc);
        }
    }
}
